// n8n Code node: Run Once for All Items. Each item is one failed job + bounded log.
const results = $input.all().map(({json:job}) => {
  const raw = typeof job.log === 'string' ? job.log : '';
  const cleaned = raw.replace(/\x1b\[[0-9;]*m/g,'').replace(/^\d{4}-\d{2}-\d{2}T[\d:.]+Z\s?/gm,'').replace(/\b(?:gh[pousr]_[A-Za-z0-9_]{15,}|github_pat_[A-Za-z0-9_]+)\b/g,'[REDACTED]')
    .replace(/(authorization\s*[:=]\s*(?:bearer|basic)?\s*)\S+/ig,'$1[REDACTED]')
    .replace(/((?:password|secret|access_token|refresh_token|api_key)\s*[:=]\s*)[^\s,;]+/ig,'$1[REDACTED]')
    .replace(/(https?:\/\/[^\s?]+)\?[^\s]+/g,'$1?[REDACTED_QUERY]');
  const patterns = {
    COMPILE_ERROR: /compilation (?:failed|error)|unresolved reference|cannot find symbol|(?:^|\n).*\.(?:java|kt):\d+(?::\d+)?:?\s*(?:error|unresolved)|(?:^|\n)e: file:\/\/|> Task :[^\n]*compile\w* FAILED/im,
    TEST_FAILURE: /there were failing tests|\bAssertionFailedError\b|\bAssertionError\b|\b\d+ tests? completed, \d+ failed\b|\w+\s*>\s*[^\n]+\s+FAILED/i,
    APPLICATION_CONTEXT_ERROR: /failed to load ApplicationContext|ApplicationContext failure threshold|APPLICATION FAILED TO START|BeanCreationException|UnsatisfiedDependencyException/i,
    LINT_ERROR: /(?:ktlint|detekt|checkstyle|pmd)[^\n]*(?:FAILED|violation|failed)|(?:lint|style) violations? found/i,
    DEPENDENCY_ERROR: /could not resolve all (?:files|dependencies)|could not (?:find|resolve|download) [\w.:-]+|could not (?:GET|HEAD) ['"]?https?:|PKIX path building failed|Plugin \[id:.*was not found/i,
    INFRA_ERROR: /no space left on device|cannot connect to the Docker daemon|connection refused|runner (?:lost|disconnected)|the operation was canceled|job exceeded the maximum execution time|out of memory|Cannot allocate memory|ENOSPC|EAI_AGAIN/i
  };
  let categories=Object.entries(patterns).filter(([,r])=>r.test(cleaned)).map(([name])=>name);
  // Context initialization failures commonly cascade into generic test failures.
  if(categories.includes('APPLICATION_CONTEXT_ERROR')) categories=categories.filter(c=>c!=='TEST_FAILURE');
  // Gradle wraps dependency/lint failures in generic compilation/test task errors.
  if(categories.includes('DEPENDENCY_ERROR')) categories=categories.filter(c=>c!=='COMPILE_ERROR');
  if(categories.includes('LINT_ERROR') && !/AssertionFailedError|AssertionError/.test(cleaned))categories=categories.filter(c=>c!=='TEST_FAILURE');
  if(!categories.length && job.conclusion==='timed_out')categories=['INFRA_ERROR'];
  const failureType=categories.length===1?categories[0]:'UNKNOWN';
  const incomplete=job.logStatus!=='AVAILABLE' || job.logTruncated===true || job.jobsIncomplete===true;
  const aiAnalysisRequired=incomplete || categories.length!==1 || failureType==='APPLICATION_CONTEXT_ERROR';
  const tests = new Set();
  for(const match of cleaned.matchAll(/^[ \t]*([A-Za-z_$][\w.$]*)[ \t]+>[ \t]+([^\r\n]+?)[ \t]+FAILED[ \t]*$/gm))tests.add(match[1]+' > '+match[2].trim());
  const lines=cleaned.split(/\r?\n/), selected=new Set();
  for(let i=0;i<lines.length;i++)if(/\bERROR\b|\bFAILURE\b|\bFAILED\b|Exception|Caused by|[Uu]nresolved reference|cannot find symbol|[Cc]ould not resolve|[Cc]ould not find|[Cc]onnection refused|[Nn]o space left/.test(lines[i]))for(let j=Math.max(0,i-1);j<=Math.min(lines.length-1,i+2);j++)selected.add(j);
  if(!selected.size)for(let i=Math.max(0,lines.length-30);i<lines.length;i++)selected.add(i);
  const indexes=[...selected].sort((a,b)=>a-b);
  const excerpt=indexes.slice(0,160).map(i=>`${i+1}: ${lines[i]}`).join('\n').slice(0,12000);
  return {runId:job.runId,runAttempt:job.runAttempt,headSha:job.headSha,jobId:job.jobId,jobName:job.jobName,conclusion:job.conclusion,
    failedSteps:job.failedSteps||[],failureType,categories,aiAnalysisRequired,failedTests:[...tests].slice(0,30),
    logStatus:job.logStatus,logTruncated:job.logTruncated===true,jobsIncomplete:job.jobsIncomplete===true,
    excerpt,excerptTruncated:indexes.length>160 || indexes.map(i=>lines[i]).join('\n').length>12000,
    reasons:[...(incomplete?['INCOMPLETE_LOG_OR_JOBS']:[]),...(categories.length>1?['MULTIPLE_FAILURE_TYPES']:[]),...(!categories.length?['NO_RECOGNIZED_PATTERN']:[]),...(failureType==='APPLICATION_CONTEXT_ERROR'?['CONTEXT_FAILURE_NEEDS_ANALYSIS']:[])]};
});
const categories=[...new Set(results.flatMap(r=>r.categories))];
return [{json:{schemaVersion:1,analysisStatus:results.some(r=>r.logStatus!=='AVAILABLE'||r.logTruncated||r.jobsIncomplete)?'PARTIAL':'COMPLETED',
  runId:results[0]?.runId,runAttempt:results[0]?.runAttempt,headSha:results[0]?.headSha,
  failureType:categories.length===1 && results.every(r=>r.failureType!=='UNKNOWN')?categories[0]:'UNKNOWN',
  categories,aiAnalysisRequired:results.length===0||categories.length!==1||results.some(r=>r.aiAnalysisRequired),
  failedJobCount:results.length,jobs:results,aiInvoked:false}}];

const c=$('Classify CI Failure').first().json;
if ($json.statusCode!==200 || !Array.isArray($json.body)) return [];
const matches=$json.body.filter(pr => pr?.state==='open' && pr?.base?.ref==='dev' && pr?.head?.sha===c.headSha && Number.isInteger(pr?.number));
if (!matches.length) return [];
matches.sort((a,b)=>a.number-b.number);
return [{json:{status:'RUN',repository:'prgrms-be-devcourse/NBE11-13-3-Team03',prNumber:matches[0].number,headSha:c.headSha}}];

const c=$('Classify CI Failure').first().json;
if ($json.statusCode!==200) return [];
const pr=$json.body;
if (pr?.state!=='open' || pr?.base?.ref!=='dev' || pr?.head?.sha!==c.headSha || !Number.isInteger(pr?.number)) return [];
return [{json:{status:'RUN',repository:'prgrms-be-devcourse/NBE11-13-3-Team03',prNumber:pr.number,headSha:c.headSha,pr}}];

const c=$('Classify CI Failure').first().json;
const target=$('Validate CI Target PR').first().json;
const pr=target.pr;
const identity=$('Get CI Analysis Identity').first().json;
const ruleSummaryRequired=c.aiAnalysisRequired===false;
const prefix=ruleSummaryRequired?'gudit-ci-result':'gudit-ci-analysis';
const marker=`<!-- ${prefix}:v1:${c.runId}:${c.runAttempt}:${c.headSha} -->`;
if (ruleSummaryRequired && !['COMPILE_ERROR','TEST_FAILURE','LINT_ERROR','DEPENDENCY_ERROR','INFRA_ERROR'].includes(c.failureType)) return [{json:{status:'SKIPPED',reason:'NO_SUPPORTED_FAILURE'}}];
if (identity.statusCode!==200 || !identity.body?.id) return [{json:{status:'ERROR',reason:'IDENTITY_LOOKUP_FAILED'}}];
for (const item of $('Get Existing CI Analyses').all()) {
  if (item.json.statusCode!==200 || !Array.isArray(item.json.body)) return [{json:{status:'ERROR',reason:'COMMENT_LOOKUP_FAILED'}}];
  if (item.json.body.some(comment => comment.user?.id===identity.body.id && typeof comment.body==='string' && comment.body.includes(marker))) return [{json:{status:'SKIPPED',reason:'ALREADY_COMMENTED',marker}}];
}
const byPath=new Map();
for (const item of $input.all()) {
  if (item.json.statusCode!==200 || !Array.isArray(item.json.body)) return [{json:{status:'ERROR',reason:'PR_FILE_LOOKUP_FAILED'}}];
  for (const file of item.json.body) {
    if (!file?.filename || byPath.has(file.filename)) return [{json:{status:'ERROR',reason:'INVALID_PR_FILES'}}];
    byPath.set(file.filename,{filename:file.filename,status:file.status,additions:file.additions,deletions:file.deletions,patch:typeof file.patch==='string'?file.patch:null});
  }
}
const allFiles=[...byPath.values()];
if (!Number.isInteger(pr.changed_files) || pr.changed_files<0 || pr.changed_files>3000 || allFiles.length!==pr.changed_files) return [{json:{status:'ERROR',reason:'INCOMPLETE_PR_FILES'}}];
const failedTests=c.jobs.flatMap(job => Array.isArray(job.failedTests)?job.failedTests:[]);
const evidenceText=(failedTests.join(' ')+' '+c.jobs.map(job=>job.excerpt||'').join(' ')).toLowerCase();
const tokens=new Set(failedTests.flatMap(name=>String(name).match(/[A-Za-z_$][A-Za-z0-9_$]{3,}/g)||[]).map(x=>x.toLowerCase()));
const score=file=>{
  const path=file.filename.toLowerCase(); const base=path.split('/').pop().replace(/\.(java|kt|kts)$/,''); let value=0;
  if (tokens.has(base)) value+=120;
  if (evidenceText.includes(base) && base.length>3) value+=80;
  if (/src\/test\//.test(path)) value+=30;
  if (/src\/main\//.test(path)) value+=20;
  if (/(build\.gradle|settings\.gradle|\.github\/workflows)/.test(path)) value+=15;
  if (/^(docs\/)|\.(md|png|jpe?g|gif|webp|ico|svg)$/i.test(path)) value-=100;
  if (!file.patch) value-=5;
  return value;
};
const ranked=allFiles.map(file=>({...file,_score:score(file)})).filter(file=>file._score>=0).sort((a,b)=>b._score-a._score || a.filename.localeCompare(b.filename));
const selected=[]; let diffChars=0;
for (const file of ranked.slice(0,30)) {
  if (selected.length>=20) break;
  const allowance=Math.max(0,20000-diffChars);
  const patch=file.patch===null?null:file.patch.slice(0,Math.min(5000,allowance));
  if (file.patch!==null && !patch.length) continue;
  selected.push({filename:file.filename,status:file.status,patch,patchTruncated:file.patch!==null && patch.length<file.patch.length,score:file._score});
  diffChars+=patch?.length||0;
}
const logs=[]; let logChars=0;
for (const job of c.jobs.slice(0,4)) {
  const allowance=Math.max(0,18000-logChars); if (!allowance) break;
  const excerpt=String(job.excerpt||'').slice(0,Math.min(6000,allowance));
  logs.push({jobName:job.jobName,failedSteps:job.failedSteps,failureType:job.failureType,failedTests:job.failedTests,excerpt,excerptTruncated:job.excerptTruncated===true || excerpt.length<String(job.excerpt||'').length,logStatus:job.logStatus});
  logChars+=excerpt.length;
}
const run=$('Get CI Run').first().json.body;
const payload={repository:target.repository,prNumber:target.prNumber,runId:c.runId,runAttempt:c.runAttempt,headSha:c.headSha,marker,aiAnalysisRequired:c.aiAnalysisRequired===true,ruleSummaryRequired,
  workflowName:String(run?.name||'').slice(0,120),runUrl:String(run?.html_url||'').slice(0,500),title:String(pr.title||'').slice(0,200),description:String(pr.body||'').slice(0,1200),
  classification:{analysisStatus:c.analysisStatus,failureType:c.failureType,categories:c.categories,failedJobCount:c.failedJobCount},jobs:c.jobs.map(job=>({jobName:job.jobName,failedSteps:job.failedSteps,failedTests:job.failedTests,failureType:job.failureType,reasons:job.reasons})).slice(0,4),
  logs,files:selected,omittedFileCount:Math.max(0,allFiles.length-selected.length),inputStats:{changedFileCount:allFiles.length,fileCount:selected.length,diffChars,logChars,logsTruncated:logs.some(x=>x.excerptTruncated)}};
const raw=JSON.stringify(payload);
if (raw.length>70000) return [{json:{status:'SKIPPED',reason:'INPUT_TOO_LARGE',marker,inputStats:payload.inputStats}}];
const encoded=Buffer.from(raw,'utf8').toString('base64');
if (encoded.length>120000 || !/^[A-Za-z0-9+/=]+$/.test(encoded)) return [{json:{status:'ERROR',reason:'INVALID_ENCODING'}}];
return [{json:{status:'RUN',marker,prNumber:target.prNumber,headSha:c.headSha,runId:c.runId,runAttempt:c.runAttempt,inputStats:payload.inputStats,command:"/usr/bin/python3 /root/ai-workflow/ci-analyzer/ci_failure_analyzer.py '"+encoded+"'"}}];

try {
  if ($json.error) return [{json:{status:'ERROR',reason:'WORKER_EXECUTION_FAILED',shouldPost:false}}];
  const result=JSON.parse($json.stdout??'{}');
  if (!['READY','SKIPPED','ERROR'].includes(result.status)) throw new Error('invalid status');
  return [{json:{...result,aiInvoked:result.aiInvoked===true,shouldPost:result.status==='READY' && typeof result.body==='string' && result.body.length>0}}];
} catch { return [{json:{status:'ERROR',reason:'INVALID_WORKER_OUTPUT',aiInvoked:false,shouldPost:false}}]; }

const c=$('Classify CI Failure').first().json;
const result=$('Normalize Failure Analysis').first().json;
const run=$('Verify Analysis CI Run').first().json;
const pr=$json;
const runOk=run.statusCode===200 && run.body?.status==='completed' && ['failure','timed_out','startup_failure','action_required'].includes(run.body?.conclusion) && run.body?.id===c.runId && run.body?.run_attempt===c.runAttempt && run.body?.head_sha===c.headSha;
const prOk=pr.statusCode===200 && pr.body?.state==='open' && pr.body?.base?.ref==='dev' && pr.body?.head?.sha===c.headSha;
const ok=runOk && prOk;
return [{json:{...result,status:ok?'READY':'SKIPPED',reason:ok?null:'CI_OR_PR_CHANGED_DURING_ANALYSIS',shouldPost:ok,runId:c.runId,runAttempt:c.runAttempt,headSha:c.headSha,prNumber:$('Validate CI Target PR').first().json.prNumber}}];

const classification = $('Classify CI Failure').first().json;
const result = $input.first().json;
const tests = [...new Set((classification.jobs || []).flatMap(job => Array.isArray(job.failedTests) ? job.failedTests : []).map(String).filter(Boolean))].slice(0, 12);
if (result.status !== 'READY' || result.shouldPost !== true || tests.length === 0) return [];
const run = $('Get CI Run').first().json.body || {};
const target = $('Validate CI Target PR').first().json;
const clean = String(result.body || '')
  .replace(/<!--[\s\S]*?-->/g, '')
  .replace(/<[^>]+>/g, '')
  .replace(/@/g, '＠')
  .trim()
  .slice(0, 2400);
const testLines = tests.map(name => `• ${name.replace(/@/g, '＠').slice(0, 240)}`).join('\n');
const text = [
  ':rotating_light: *Gudit CI 테스트 실패*',
  `• PR: #${target.prNumber}`,
  `• 분류: ${classification.failureType}`,
  `• Commit: ${classification.headSha}`,
  `• Actions: ${String(run.html_url || '').slice(0, 500)}`,
  '',
  '*실패한 테스트*',
  testLines,
  '',
  '*실패 원인 분석*',
  clean || '분석 결과를 생성하지 못했습니다.',
].join('\n').slice(0, 3500);
const payload = {
  repository: 'prgrms-be-devcourse/NBE11-13-3-Team03',
  prNumber: target.prNumber,
  runId: classification.runId,
  runAttempt: classification.runAttempt,
  headSha: classification.headSha,
  text,
};
const encoded = Buffer.from(JSON.stringify(payload), 'utf8').toString('base64');
return [{ json: { status: 'RUN', command: "/usr/bin/python3 /root/ai-workflow/slack/send_slack_ci_alert.py '" + encoded + "'" } }];
